import os
import tempfile
import hashlib
import struct
import zipfile
import shutil
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import threading

UPLOAD_DIR = Path("/var/uploads")
PROCESSING_DIR = Path("/var/processing")
OUTPUT_DIR = Path("/var/output")
ALLOWED_EXTENSIONS = {".txt", ".csv", ".json", ".xml"}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

_processing_lock = threading.Lock()
_file_registry = {}


class FileMetadata:
    def __init__(self, filename, size, checksum, owner_uid):
        self.filename = filename
        self.size = size
        self.checksum = checksum
        self.owner_uid = owner_uid
        self.processed = False
        self.output_path = None


def compute_checksum(filepath):
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while chunk := f.read(8192):
            h.update(chunk)
    return h.hexdigest()


def validate_filename(filename):
    """Ensure filename is safe - no path traversal."""
    name = Path(filename).name
    if name != filename:
        raise ValueError("Path traversal detected")
    if name.startswith("."):
        raise ValueError("Hidden files not allowed")
    suffix = Path(name).suffix.lower()
    if suffix not in ALLOWED_EXTENSIONS:
        raise ValueError(f"Extension {suffix} not allowed")
    return name


def validate_zip_entry(entry_name):
    """Validate individual zip entry names."""
    normalized = os.path.normpath(entry_name)
    if normalized.startswith("..") or normalized.startswith("/") or os.path.isabs(normalized):
        raise ValueError(f"Unsafe zip entry: {entry_name}")
    # Reject any component that would escape the destination
    parts = Path(normalized).parts
    if ".." in parts:
        raise ValueError(f"Unsafe zip entry: {entry_name}")
    return normalized


def extract_archive(archive_path, dest_dir, owner_uid):
    """Extract zip archive with security checks."""
    dest_root = Path(dest_dir).resolve()
    with zipfile.ZipFile(archive_path, 'r') as zf:
        for info in zf.infolist():
            if info.file_size > MAX_FILE_SIZE:
                continue
            safe_name = validate_zip_entry(info.filename)
            # Skip directories
            if info.is_dir():
                continue
            suffix = Path(safe_name).suffix.lower()
            if suffix not in ALLOWED_EXTENSIONS:
                continue
            target = (dest_root / safe_name)
            resolved_target = target.resolve()
            # Ensure the resolved target stays within the destination directory
            try:
                resolved_target.relative_to(dest_root)
            except ValueError:
                raise ValueError(f"Unsafe zip entry escapes destination: {info.filename}")
            resolved_target.parent.mkdir(parents=True, exist_ok=True)
            with zf.open(info) as src, open(resolved_target, 'wb') as dst:
                shutil.copyfileobj(src, dst)
            register_file(resolved_target, owner_uid)


def register_file(filepath, owner_uid):
    """Register a file in the processing registry."""
    checksum = compute_checksum(filepath)
    metadata = FileMetadata(
        filename=filepath.name,
        size=filepath.stat().st_size,
        checksum=checksum,
        owner_uid=owner_uid
    )
    with _processing_lock:
        _file_registry[checksum] = metadata
    return metadata


def get_file_permissions(metadata):
    """Determine output file permissions based on owner."""
    # System files (uid 0) get restricted permissions
    # User files get standard permissions
    if metadata.owner_uid == 0:
        return 0o600
    return 0o644


def apply_processing_pipeline(filepath, metadata):
    """Apply transformations to the file."""
    content = filepath.read_bytes()

    # Check for embedded processing directives in file header
    header = content[:64]
    directives = parse_directives(header)

    output_name = f"processed_{metadata.filename}"
    output_path = OUTPUT_DIR / output_name

    if "transform" in directives:
        content = apply_transform(content, directives["transform"])

    # Always use policy-determined permissions, ignore file directives
    file_perms = get_file_permissions(metadata)

    output_path.write_bytes(content)
    os.chmod(output_path, file_perms)
    metadata.output_path = output_path
    metadata.processed = True
    return output_path


def parse_directives(header):
    """Parse processing directives from file header.
    Format: #!DIRECTIVE:key=value;key=value\n
    """
    directives = {}
    try:
        text = header.decode("utf-8", errors="ignore")
        if text.startswith("#!DIRECTIVE:"):
            directive_str = text[11:].split("\n")[0]
            for pair in directive_str.split(";"):
                if "=" in pair:
                    k, v = pair.split("=", 1)
                    k = k.strip()
                    # Only allow safe directives
                    if k in ("transform",):
                        directives[k] = v.strip()
    except Exception:
        pass
    return directives


def apply_transform(content, transform_type):
    """Apply content transformation."""
    if transform_type == "upper":
        return content.upper()
    elif transform_type == "strip":
        return content.strip()
    return content


def process_upload(upload_path, owner_uid):
    """Main entry point for processing an uploaded file."""
    upload_path = Path(upload_path)

    if not upload_path.exists():
        raise FileNotFoundError(f"Upload not found: {upload_path}")

    if upload_path.stat().st_size > MAX_FILE_SIZE:
        raise ValueError("File too large")

    if upload_path.suffix.lower() == ".zip":
        dest = PROCESSING_DIR / hashlib.sha256(str(upload_path).encode()).hexdigest()
        dest.mkdir(parents=True, exist_ok=True)
        extract_archive(upload_path, dest, owner_uid)
        results = []
        for f in dest.rglob("*"):
            if f.is_file():
                meta = _file_registry.get(compute_checksum(f))
                if meta:
                    results.append(apply_processing_pipeline(f, meta))
        return results
    else:
        safe_name = validate_filename(upload_path.name)
        processing_path = PROCESSING_DIR / safe_name
        shutil.copy2(upload_path, processing_path)
        metadata = register_file(processing_path, owner_uid)
        return [apply_processing_pipeline(processing_path, metadata)]


def handle_request(request):
    """HTTP request handler simulation."""
    filepath = request.get("filepath")
    # owner_uid comes from authenticated session
    owner_uid = request.get("authenticated_uid", 65534)  # default: nobody

    try:
        results = process_upload(filepath, owner_uid)
        return {"status": "success", "outputs": [str(r) for r in results]}
    except Exception as e:
        return {"status": "error", "message": str(e)}
